// Deterministic PRNG: mulberry32 (seeded with workflow execution ID)
function mulberry32(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}
const rng = mulberry32($json._execution_seed || 12345);
const data = $input.first().json;
const scores = {};
(data.ratings || []).forEach(r => { scores[r.company] = {E: rng() * 10, S: rng() * 10, G: rng() * 10, overall: rng() * 10}; });
const ranking = Object.entries(scores).sort((a, b) => b[1].overall - a[1].overall).map(([c, s], i) => ({rank: i+1, company: c, score: s.overall}));
const changes = (data.ratings || []).filter(r => Math.abs(r.change || 0) > 0.5).map(r => ({company: r.company, old: r.previous, new: r.current, delta: r.change}));
return [{json: {esg_scores: scores, sector_ranking: ranking, rating_changes: changes, trend_analysis: {improving: 3, stable: 5, deteriorating: 2}, timestamp: new Date().toISOString()}}];
